INSERT INTO MEDICAL_RECORD (record_id, appointment_id, patient_id, specialist_id, diagnosis, clinical_notes, treatment_plan, record_date, deleted_at) VALUES
('a8141ccd-4834-422a-8acc-25ec632bae54', 'e8b895c9-96c9-4641-9bb2-881c7c4e3bc3', '1d05d1bb-2fb9-427d-b13c-bcaafcf53868', NULL, 'Đau đầu do căng thẳng cơ căng thẳng tâm lý (Tension Headache) (ICD-10: G44.2)', 'Đau ê ẩm vùng chẩm hai bên như bị thắt dải băng quanh đầu, làm việc máy tính nhiều, ngủ chập chờn.', 'Điều chỉnh thời gian làm việc và nghỉ ngơi, tránh thức khuya, tập thư giãn vùng cổ vai gáy, uống vitamin bổ thần kinh.', '2026-09-02 16:00:00', NULL),
('7b5dd811-71aa-41c1-b8f5-b3f7e58fba79', '3f46607d-c0f4-43e1-9f50-2a0165b73167', '851eb5d2-c711-47a2-8465-e7e95da1d158', '84ebed80-ebe3-4cd2-97c0-d13e7b09cd36', 'Viêm phế quản cấp thể co thắt (ICD-10: J20.9)', 'Ho khan từng cơn nhiều về đêm, có đờm trắng loãng, đau rát họng, nghe phổi có ít rale rít rải rác.', 'Kháng sinh đủ liều 7 ngày, uống nhiều nước ấm, súc họng nước muối, xịt giãn phế quản khi khó thở nhiều.', '2026-09-04 09:00:00', NULL),
('68ca08d5-6550-4d32-9f33-4dc1467a8e16', '49722aaa-7b6f-4f2e-8eb0-35e17d4e9a1e', 'c8243b2d-9772-4f98-9208-fbd27a1607f1', NULL, 'Rối loạn lipid máu hỗn hợp (ICD-10: E78.2)', 'Khám sức khỏe định kỳ phát hiện Cholesterol toàn phần 6.5 mmol/L, Triglyceride 2.8 mmol/L, thể trạng thừa cân nhẹ (BMI 24.5).', 'Chế độ ăn giảm chất béo bão hòa và nội tạng động vật, tăng cường rau xanh, duy trì chạy bộ 45p/ngày.', '2026-09-01 11:00:00', NULL),
('8ecdc8da-47b5-4177-bd69-a2e1f3491bec', '80c1ca95-1ac2-4aae-9f28-78a0bfe9812a', '7f9c8e5a-79a4-40b3-bd5e-d0a547125844', NULL, 'Cảm cúm thông thường kèm viêm họng cấp (ICD-10: J00 / J02.9)', 'Mệt mỏi, sốt gai rét 38.2 độ, đau rát cổ họng, nuốt đau, hắt hơi chảy nước mũi trong. Khám họng niêm mạc đỏ.', 'Nghỉ ngơi hợp lý, uống nhiều nước ấm, súc họng bằng dung dịch sát khuẩn, dùng thuốc theo đơn 5 ngày.', '2026-09-08 14:00:00', NULL),
('8821f49a-b71b-43e2-bf8f-ca65c6539a72', '647b78ac-e2e3-4e87-81cc-5982777545ac', 'b95ebf9f-8b41-40d8-b897-ad407742f381', '533f9540-8d88-44de-bfba-fe2f88c70b12', 'Tăng huyết áp vô căn độ 2 (ICD-10: I10)', 'Huyết áp phòng khám 150/95 mmHg, nhịp tim 82 l/p. Tiếng tim T1, T2 đều rõ. Chưa ghi nhận phù ngoại biên.', 'Kiểm soát huyết áp bằng thuốc hàng ngày, hạn chế ăn mặn (<5g muối/ngày), tập thể dục nhẹ nhàng 30p/ngày.', '2026-09-13 15:00:00', NULL),
('a979f8ad-cf93-42db-bd00-ee682114ce7f', 'c82ec079-8397-4e42-b74f-baadc56fa426', '75f18e3d-5175-41d4-959e-d98e8d461fcc', NULL, 'Rối loạn lipid máu hỗn hợp (ICD-10: E78.2)', 'Khám sức khỏe định kỳ phát hiện Cholesterol toàn phần 6.5 mmol/L, Triglyceride 2.8 mmol/L, thể trạng thừa cân nhẹ (BMI 24.5).', 'Chế độ ăn giảm chất béo bão hòa và nội tạng động vật, tăng cường rau xanh, duy trì chạy bộ 45p/ngày.', '2026-09-05 17:00:00', NULL),
('3f20b3fe-ebcb-4806-9c6e-391f522c3f75', 'af5bbefe-779c-4506-9554-d1d40b6f9fb4', 'abb1c9a3-0f1a-434a-8e19-b2e33dfe0eda', '0e5e6155-1cfb-48bf-b99d-daab23b7b5b4', 'Viêm da tiếp xúc dị ứng cấp tính (ICD-10: L23)', 'Nổi ban đỏ, mụn nước nhỏ rải rác ở hai cẳng tay sau khi tiếp xúc hóa chất tẩy rửa. Ngứa nhiều.', 'Tránh tiếp xúc chất tẩy rửa, bôi kem dưỡng ẩm và thuốc làm dịu da 2 lần/ngày, uống thuốc chống dị ứng.', '2026-09-17 16:00:00', NULL),
('9b97ffbc-b4c1-4eb5-8e33-3813a5af9cd9', '9419fbf8-9502-4703-a8fe-4ebac3796a75', 'badd83b3-aa17-4b00-9d19-5d2183c618d3', NULL, 'Cảm cúm thông thường kèm viêm họng cấp (ICD-10: J00 / J02.9)', 'Mệt mỏi, sốt gai rét 38.2 độ, đau rát cổ họng, nuốt đau, hắt hơi chảy nước mũi trong. Khám họng niêm mạc đỏ.', 'Nghỉ ngơi hợp lý, uống nhiều nước ấm, súc họng bằng dung dịch sát khuẩn, dùng thuốc theo đơn 5 ngày.', '2026-09-17 14:00:00', NULL),
('59f95d28-e069-4e66-9e67-6944d070055b', '7130ae24-c752-4121-beee-1f0c5a3a9648', 'be2f7b10-8c10-4e47-8096-b619793fc786', NULL, 'Rối loạn lipid máu hỗn hợp (ICD-10: E78.2)', 'Khám sức khỏe định kỳ phát hiện Cholesterol toàn phần 6.5 mmol/L, Triglyceride 2.8 mmol/L, thể trạng thừa cân nhẹ (BMI 24.5).', 'Chế độ ăn giảm chất béo bão hòa và nội tạng động vật, tăng cường rau xanh, duy trì chạy bộ 45p/ngày.', '2026-09-02 14:00:00', NULL),
('e07dd89e-b66f-45c7-a69f-d7ad9d8f57b0', 'e7c7c461-f954-49f7-a802-123e540a8540', '37c48203-bc38-450f-b640-4c8feaa3a711', NULL, 'Đau đầu do căng thẳng cơ căng thẳng tâm lý (Tension Headache) (ICD-10: G44.2)', 'Đau ê ẩm vùng chẩm hai bên như bị thắt dải băng quanh đầu, làm việc máy tính nhiều, ngủ chập chờn.', 'Điều chỉnh thời gian làm việc và nghỉ ngơi, tránh thức khuya, tập thư giãn vùng cổ vai gáy, uống vitamin bổ thần kinh.', '2026-09-02 08:30:00', NULL),
('0dceb583-e215-49d2-9a97-2096fd20b4e2', '9fa97616-a606-4fd7-8d18-50a17daca2ec', '2bc3a046-d027-42d1-a0e8-fd2dec87f8e2', 'a96bba46-05ad-4e78-8d7e-1ef7a8206e3e', 'Viêm mũi xoang dị ứng đợt cấp (ICD-10: J30.4)', 'Ngạt mũi, hắt hơi thành tràng liên tục khi gặp lạnh, chảy dịch mũi trong, ngứa mũi và mắt.', 'Xịt rửa mũi bằng nước muối sinh lý hàng ngày, xịt thuốc co mạch mũi khi ngạt nặng, uống kháng histamine.', '2026-09-07 16:00:00', NULL),
('5be462d9-dcfa-4162-b738-6f1e0da80c90', '3c30ea1c-0310-496a-b697-b46fbe89b51f', '0376e295-1d6c-491e-bbce-56bcf20d59ba', 'a25886da-6dc5-4ea2-bc95-7b5623afdaab', 'Đái tháo đường type 2 không phụ thuộc Insulin (ICD-10: E11)', 'Đường huyết đói 8.2 mmol/L, HbA1c 7.6%. Bệnh nhân cảm giác hay khát nước, tiểu nhiều về đêm.', 'Tuân thủ dùng thuốc đúng giờ trước/sau ăn, kiêng đồ ngọt tinh luyện, theo dõi đường huyết mao mạch định kỳ.', '2026-09-12 10:00:00', NULL),
('e1ff544e-3b9c-47d2-8d53-551cb47b770a', '76e6d80b-dd51-48ed-8091-899ec1815472', '9db9d815-3885-45db-92a9-f6f3874b0cf3', NULL, 'Đau đầu do căng thẳng cơ căng thẳng tâm lý (Tension Headache) (ICD-10: G44.2)', 'Đau ê ẩm vùng chẩm hai bên như bị thắt dải băng quanh đầu, làm việc máy tính nhiều, ngủ chập chờn.', 'Điều chỉnh thời gian làm việc và nghỉ ngơi, tránh thức khuya, tập thư giãn vùng cổ vai gáy, uống vitamin bổ thần kinh.', '2026-09-03 09:00:00', NULL),
('9971802b-22ae-4cf0-9736-31ca80cdced4', 'c8369285-42ab-4826-8498-3293d62ded91', 'c729b96a-e6ac-49c5-9625-f4ccac852b5c', 'a2ef2836-d5f7-48a9-a9e6-de8f5e4cc8df', 'Tăng huyết áp vô căn độ 2 (ICD-10: I10)', 'Huyết áp phòng khám 150/95 mmHg, nhịp tim 82 l/p. Tiếng tim T1, T2 đều rõ. Chưa ghi nhận phù ngoại biên.', 'Kiểm soát huyết áp bằng thuốc hàng ngày, hạn chế ăn mặn (<5g muối/ngày), tập thể dục nhẹ nhàng 30p/ngày.', '2026-09-22 09:00:00', NULL),
('57bcc0fb-9319-4edf-bb64-db50059574f3', 'e1c97677-c0b7-4263-abf6-6c6a5d2a0257', 'e7e7bc3f-daa9-4684-88fe-50bda58df198', '0d00988a-e8ab-4b43-92a5-bbb2cb0ece9a', 'Đái tháo đường type 2 không phụ thuộc Insulin (ICD-10: E11)', 'Đường huyết đói 8.2 mmol/L, HbA1c 7.6%. Bệnh nhân cảm giác hay khát nước, tiểu nhiều về đêm.', 'Tuân thủ dùng thuốc đúng giờ trước/sau ăn, kiêng đồ ngọt tinh luyện, theo dõi đường huyết mao mạch định kỳ.', '2026-09-23 11:30:00', NULL),
('43485d38-e02a-49d9-b43c-cd7b59a79df8', '512828d3-21f0-4e55-9ac7-8f45d96cb168', '3a2bc1da-a3ff-4b98-9093-381aefce8d81', NULL, 'Cảm cúm thông thường kèm viêm họng cấp (ICD-10: J00 / J02.9)', 'Mệt mỏi, sốt gai rét 38.2 độ, đau rát cổ họng, nuốt đau, hắt hơi chảy nước mũi trong. Khám họng niêm mạc đỏ.', 'Nghỉ ngơi hợp lý, uống nhiều nước ấm, súc họng bằng dung dịch sát khuẩn, dùng thuốc theo đơn 5 ngày.', '2026-09-12 15:30:00', NULL),
('c1853b04-3067-4e82-b0f6-8ae9261ca46e', '739fb5fe-6054-478b-b13b-b99202a4dfa9', '761f3ecd-e1c8-430d-8d25-82ccb94f703a', '918fb1e4-08b2-415b-9f9c-f8063967de9f', 'Thiểu năng tuần hoàn não - Rối loạn tiền đình ngoại biên (ICD-10: H81.0)', 'Chóng mặt quay cuồng khi thay đổi tư thế, kèm theo ù tai nhẹ và cảm giác buồn nôn, thị lực bình thường.', 'Nghỉ ngơi phòng yên tĩnh, tránh thay đổi tư thế đột ngột, uống thuốc cải thiện tuần hoàn ốc tai và tuần hoàn não.', '2026-09-15 08:30:00', NULL),
('6c0e1fb0-d672-4e13-957e-63b4b77d9018', '9afe045b-f282-42e5-b11c-619bda27b7c2', '390f5617-16e3-4895-8115-2c81a122bd93', NULL, 'Đau đầu do căng thẳng cơ căng thẳng tâm lý (Tension Headache) (ICD-10: G44.2)', 'Đau ê ẩm vùng chẩm hai bên như bị thắt dải băng quanh đầu, làm việc máy tính nhiều, ngủ chập chờn.', 'Điều chỉnh thời gian làm việc và nghỉ ngơi, tránh thức khuya, tập thư giãn vùng cổ vai gáy, uống vitamin bổ thần kinh.', '2026-09-22 10:30:00', NULL),
('af4f0015-1877-43bb-9083-b24a5ead7b70', '5144c636-2b90-42ae-9869-cd97c8499b83', '1560de7e-bba4-4ec2-b3cf-a9f18cd5b916', NULL, 'Rối loạn lipid máu hỗn hợp (ICD-10: E78.2)', 'Khám sức khỏe định kỳ phát hiện Cholesterol toàn phần 6.5 mmol/L, Triglyceride 2.8 mmol/L, thể trạng thừa cân nhẹ (BMI 24.5).', 'Chế độ ăn giảm chất béo bão hòa và nội tạng động vật, tăng cường rau xanh, duy trì chạy bộ 45p/ngày.', '2026-09-19 15:00:00', NULL),
